fn get_triple(a: &[i32]) -> usize {
    // Look at every window of three consecutive elements
    // and return the first index where all three are equal.
    a.windows(3)
     .position(|w| w[0] == w[1] && w[1] == w[2])
     .unwrap_or(a.len())
}

